// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;
    function setUp() public { c = new Size(); }

    function testFuzz_property(bytes32 role, address actor, address confirmation) public {
        vm.assume(actor != address(0));
        vm.assume(confirmation != address(0));

        bool ok;
        vm.prank(actor);
        try c.renounceRole(role, confirmation) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: renounceRole only ever succeeds when the caller
        // confirms their own account (actor == confirmation); otherwise it
        // must revert. The buggy mutant lets any caller renounce anyone's
        // role, succeeding when actor != confirmation.
        assertTrue(ok == (actor == confirmation));
    }
}
